-- KB-022 owner-approved account-recovery semantic correction. Earlier migrations remain immutable.
-- Does not modify assessment, finding, evidence or deployment decisions.
UPDATE risk_knowledge_entries SET problem_json='{"statement":"Password reset or recovery can be abused to take over a high-privilege user.","customer_symptom":"A user or operator may observe password reset or recovery can be abused to take over a high-privilege user; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"An attacker can use enumeration, reused recovery codes, expired or altered reset tokens or weak proofing to take over an account despite the normal authentication assurance.","affected_assets":["account identity and recovery records","password-reset tokens and recovery codes","identity provider and privileged access","sessions affected by recovery"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["hosted platforms"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between hosted platforms and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If password reset or recovery can be abused to take over a high-privilege user, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}',review_json='{"human_review_required":true,"last_reviewed":"2026-10-09","next_review_due":"2026-12-02","change_triggers":["ARL-KB-022 recovery, reset, identity-proofing, notification or recovery-code change","ARL-KB-022 privileged-account recovery or MFA-recovery policy change","ARL-KB-022 takeover, enumeration, token-reuse or recovery-bypass incident","ARL-KB-022 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"owner-approved semantic correction; independent practitioner validation required"}',content_digest='642ce68cf5a406ca7bd3af7b34b1f18b90b6f99c7402edb6225cf51c4205ebcf',updated_at='2026-10-09' WHERE id='ARL-KB-022';
UPDATE risk_knowledge_checks SET objective='Determine whether account recovery preserves the required authentication assurance and cannot be used to take over a privileged account through enumeration, weak proofing or reusable recovery material.',method='Test account enumeration resistance, recovery-token entropy, expiry and single-use behaviour, identity proofing, notification, recovery-code handling, session invalidation and privileged-account recovery. Verify recovery cannot silently downgrade the normal authentication assurance.',required_evidence_json='["ARL-KB-022 exact assessed system, version, environment and recovery scope","ARL-KB-022 organisation-approved recovery and identity proofing policy with MFA and privileged reset requirements","ARL-KB-022 source or configuration evidence for reset-token expiry, single-use, rate limits, proofing and session invalidation","ARL-KB-022 bounded positive evidence of authorised synthetic recovery preserving identity assurance","ARL-KB-022 bounded negative evidence for account enumeration, expired or reused tokens, weak proofing and MFA downgrade","ARL-KB-022 observed runtime recovery, identity-provider and session invalidation events","ARL-KB-022 tester and reviewer identity, role, timestamp, version and evidence digest"]',pass_condition='Authorised recovery preserves identity proofing and MFA assurance; expired and reused tokens, enumeration and weaker recovery paths cannot grant access, supported by exact-version bounded tests and accountable review.',fail_condition='Account recovery or reset permits enumeration, token replay, weak proofing, MFA downgrade or unauthorised account control, or version-bound evidence is missing.',content_digest='14dbbfd11d421290213f3b7c0cd591613e8f1a1d5833727414fd399e801dfa82',updated_at='2026-10-09' WHERE entry_id='ARL-KB-022';
